import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';

ChartJS.register(ArcElement, Tooltip, Legend);

const StatusChart = ({ running = 0, idle = 0, maintenance = 0 }) => {
  const total = running + idle + maintenance;

  const data = {
    labels: ['Running', 'Idle', 'Under Maintenance'],
    datasets: [
      {
        data: [running, idle, maintenance],
        backgroundColor: [
          'rgba(5, 150, 105, 0.9)',
          'rgba(217, 119, 6, 0.9)',
          'rgba(225, 29, 72, 0.9)',
        ],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 2,
        hoverOffset: 6,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: '#0F172A',
          font: {
            family: "'Plus Jakarta Sans', sans-serif",
            size: 12,
            weight: '800',
          },
          padding: 15,
          usePointStyle: true,
          pointStyle: 'circle',
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
        padding: 12,
        boxPadding: 6,
      },
    },
    cutout: '74%',
  };

  return (
    <div style={{ height: '260px', width: '100%', position: 'relative' }}>
      <Doughnut data={data} options={options} />
      {/* Center Donut Metric Counter */}
      <div
        style={{
          position: 'absolute',
          top: '38%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          textAlign: 'center',
          pointerEvents: 'none',
        }}
      >
        <div style={{ fontSize: '2.2rem', fontWeight: '800', color: '#0F172A', lineHeight: 1 }}>{total}</div>
        <div style={{ fontSize: '0.75rem', fontWeight: '800', color: '#334155', marginTop: '4px', letterSpacing: '0.5px' }}>
          TOTAL LOOMS
        </div>
      </div>
    </div>
  );
};

export default StatusChart;
